@startuml

class City {
  + name : string
  + inhabitants : int
}

class Attraction {
  + name : string
  + address : string
}

class GuidedTour {
  + duration : int
  + numberOfVisitors : int
}

class Person {
  + name : string
}

class Visitor extends Person {}

class Guide extends Person {}

class TourDiscount {
  + amount : float
}

City "1" -- "*" Attraction : has
Attraction "1" -- "*" GuidedTour : offers
GuidedTour "*" -- "1" Guide : requires
GuidedTour "1" -- "0..20" Visitor : can have
Visitor "0..*" -- "0..*" GuidedTour : may receive discount via
TourDiscount "*" -- "1" Visitor : for
TourDiscount "*" -- "1" GuidedTour : for

@enduml

